 function scheduleClock(){clearTimeout(clockTimer);if(selected!=='finance'||!get('finance'))return;const now=Date.now(),next=Math.min(...get('finance').shifts.filter(s=>s.end===null).map(s=>s.start+(Math.floor(Math.max(0,now-s.start)/3600000)+1)*3600000));if(Number.isFinite(next))clockTimer=setTimeout(()=>{if(!host.hidden&&selected==='finance')finance();else scheduleClock();},Math.max(1000,next-now+50));}
